/* ════════════════════════════════════════════
   CORNER MARKS — certificate-style bracket ornament
════════════════════════════════════════════ */
const CornerMarks = memo(({ size = 20, color }) => {
  const c = color || C.gold;
  const base = { position:"absolute", width:size, height:size, pointerEvents:"none" };
  return (
    <>
      <span style={{ ...base, top:-1, insetInlineStart:-1, borderTop:`1.5px solid ${c}`, borderInlineStart:`1.5px solid ${c}` }} />
      <span style={{ ...base, top:-1, insetInlineEnd:-1, borderTop:`1.5px solid ${c}`, borderInlineEnd:`1.5px solid ${c}` }} />
      <span style={{ ...base, bottom:-1, insetInlineStart:-1, borderBottom:`1.5px solid ${c}`, borderInlineStart:`1.5px solid ${c}` }} />
      <span style={{ ...base, bottom:-1, insetInlineEnd:-1, borderBottom:`1.5px solid ${c}`, borderInlineEnd:`1.5px solid ${c}` }} />
    </>
  );
});

