/* ════════════════════════════════════════════
   MEDALLION — laurel ring + star
════════════════════════════════════════════ */
const Medallion = memo(({ size = 220, animate = false }) => {
  const r = size / 2 - 10;
  const c = size / 2;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ display:"block" }}>
      <defs>
        <linearGradient id="goldRing" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#8a6a1f" />
          <stop offset="50%" stopColor="#e7c873" />
          <stop offset="100%" stopColor="#8a6a1f" />
        </linearGradient>
      </defs>
      <circle cx={c} cy={c} r={r} fill="none" stroke="url(#goldRing)" strokeWidth={2.5} />
      <circle cx={c} cy={c} r={r - 10} fill="none" stroke="url(#goldRing)" strokeWidth={1} strokeDasharray="2 5" />
      {animate && (
        <circle cx={c} cy={c} r={r} fill="none" stroke="url(#goldRing)" strokeWidth={2.5}
          strokeDasharray="660" strokeDashoffset="660"
          style={{ animation:"ringDraw 1.6s ease-out forwards" }} />
      )}
      <g style={animate ? { animation:"starDrop 1s .9s ease-out backwards" } : {}}
         transform={`translate(${c},${c})`}>
        <Star x={-22} y={-22} width={44} height={44} color={C.goldBright} fill={C.goldBright} strokeWidth={0.5} />
      </g>
    </svg>
  );
});

