/* ════════════════════════════════════════════
   EPAULETTE — كتافة الملازم تنزل في الخلفية
════════════════════════════════════════════ */
const Epaulette = memo(({ side = "right" }) => {
  const isRight = side === "right";
  return (
    <motion.div
      aria-hidden="true"
      initial={{ y: "-120%", opacity: 0, rotate: isRight ? 6 : -6 }}
      animate={{ y: 0, opacity: 1, rotate: isRight ? -4 : 4 }}
      transition={{ type: "spring", stiffness: 55, damping: 9, mass: 1.2, delay: isRight ? 0.4 : 0.8 }}
      style={{
        position: "fixed", top: 0, zIndex: 1, pointerEvents: "none",
        [isRight ? "right" : "left"]: "clamp(10px,6vw,90px)",
        transformOrigin: "top center",
      }}
    >
      {/* الخيط اللي بيتعلق منه */}
      <div style={{ width: 2, height: 40, margin: "0 auto",
        background: `linear-gradient(${C.goldBright}, transparent)`, opacity: .5 }} />

      <motion.div
        animate={{ rotate: [0, 1.6, 0, -1.6, 0] }}
        transition={{ duration: 6, repeat: Infinity, ease: "easeInOut", delay: 2 }}
        style={{ transformOrigin: "top center", opacity: .22,
                 filter: "drop-shadow(0 12px 22px rgba(0,0,0,.6))" }}
      >
        <svg width="130" height="250" viewBox="0 0 130 250">
          <defs>
            <linearGradient id={`epGold-${side}`} x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%" stopColor="#8a6a1f" />
              <stop offset="50%" stopColor="#f3d98a" />
              <stop offset="100%" stopColor="#8a6a1f" />
            </linearGradient>
            <linearGradient id={`epShine-${side}`} x1="0" y1="0" x2="1" y2="0">
              <stop offset="0%" stopColor="rgba(255,255,255,0)" />
              <stop offset="50%" stopColor="rgba(255,255,255,.55)" />
              <stop offset="100%" stopColor="rgba(255,255,255,0)" />
            </linearGradient>
            <clipPath id={`epClip-${side}`}>
              <path d="M14 8 H116 V200 L65 236 L14 200 Z" />
            </clipPath>
          </defs>

          {/* جسم الكتافة */}
          <path d="M14 8 H116 V200 L65 236 L14 200 Z"
            fill="#06101F" stroke={`url(#epGold-${side})`} strokeWidth="4" strokeLinejoin="round" />
          <path d="M26 20 H104 V194 L65 222 L26 194 Z"
            fill="none" stroke={`url(#epGold-${side})`} strokeWidth="1.5" strokeDasharray="3 4" />

          {/* زراير الأعلى */}
          <circle cx="65" cy="30" r="9" fill={`url(#epGold-${side})`} />
          <circle cx="65" cy="30" r="4" fill="#041226" />

          {/* النجمة */}
          <g transform="translate(65,112)">
            <path d="M0 -34 L10 -11 L35 -9 L16 8 L22 33 L0 20 L-22 33 L-16 8 L-35 -9 L-10 -11 Z"
              fill={`url(#epGold-${side})`} stroke="#fff6da" strokeWidth="1.2" />
          </g>

          {/* لمعة بتعدي */}
          <g clipPath={`url(#epClip-${side})`}>
            <motion.rect y="0" width="40" height="250" fill={`url(#epShine-${side})`}
              transform="skewX(-18)"
              animate={{ x: [-80, 180] }}
              transition={{ duration: 2.4, repeat: Infinity, repeatDelay: 3.5, ease: "easeInOut", delay: 2.5 }} />
          </g>
        </svg>
      </motion.div>
    </motion.div>
  );
});
/* ════════════════════════════════════════════
   AMBIENT FIELD — quiet dot texture on navy
════════════════════════════════════════════ */
const AmbientField = memo(() => {
  const dots = useRef(
    Array.from({ length: 12 }, (_, i) => ({
      id:i, x:(i * 8.1 + 4) % 100, y:(i * 12.3 + 6) % 100,
      size:2 + (i % 2), delay:(i * .4).toFixed(2), dur:(3.4 + (i % 3)).toFixed(2),
    }))
  ).current;
  return (
    <div style={{ position:"fixed", inset:0, pointerEvents:"none", zIndex:0, overflow:"hidden", background:C.navy }}>
      <div style={{ position:"absolute", inset:0, opacity:.35,
        backgroundImage:`radial-gradient(${C.goldLineSoft} 1px, transparent 1px)`,
        backgroundSize:"36px 36px" }} />
      <div style={{ position:"absolute", top:"50%", left:"50%", transform:"translate(-50%,-50%)", width:"min(72vw,760px)", height:"min(72vh,760px)", opacity:.12, filter:"saturate(.78) contrast(1.12) drop-shadow(0 0 24px rgba(232,199,102,.22))" }}>
        <div className="ministry-glow" style={{ position:"absolute", inset:"-18%", borderRadius:"50%", background:`radial-gradient(circle,${C.goldLineSoft},transparent 68%)` }} />
        <img src={MINISTRY_LOGO} alt="" aria-hidden="true" style={{ position:"relative", width:"100%", height:"100%", objectFit:"contain", display:"block", mixBlendMode:"screen" }} />
      </div>
      {dots.map(d => (
        <div key={d.id} style={{
          position:"absolute", left:`${d.x}%`, top:`${d.y}%`,
          width:d.size, height:d.size, borderRadius:"50%", background:C.goldBright,
          animation:`dustFloat ${d.dur}s ${d.delay}s ease-in-out infinite`,
        }} />
      ))}
    </div>
  );
});

/* ════════════════════════════════════════════
   AUDIO TOGGLE — siren / anthem player
════════════════════════════════════════════ */
const AnthemPlayer = memo(() => {
  const [playing, setPlaying]   = useState(false);
  const [prompted, setPrompted] = useState(false);
  const [ripples, setRipples]   = useState([]);
  const audioRef   = useRef(null);
  const startedRef = useRef(false);

  useEffect(() => {
    const audio = new Audio(ANTHEM_URL);
    audio.loop = true;
    audio.volume = 0.5;
    audio.preload = "auto";
    audioRef.current = audio;
    audio.play().then(() => { startedRef.current = true; setPlaying(true); }).catch(() => setPrompted(true));
    const onGesture = () => {
      if (startedRef.current) return;
      audio.play().then(() => { startedRef.current = true; setPlaying(true); setPrompted(false); }).catch(() => {});
    };
    ["click","touchstart","scroll","keydown"].forEach(e =>
      window.addEventListener(e, onGesture, { once:true, passive:true })
    );
    return () => {
      audio.pause(); audio.src = "";
      ["click","touchstart","scroll","keydown"].forEach(e => window.removeEventListener(e, onGesture));
    };
  }, []);

  const addRipple = () => {
    const id = Date.now();
    setRipples(p => [...p, id]);
    setTimeout(() => setRipples(p => p.filter(r => r !== id)), 900);
  };
  const toggle = useCallback(() => {
    const a = audioRef.current; if (!a) return;
    if (playing) { a.pause(); setPlaying(false); }
    else { a.play().catch(()=>{}); setPlaying(true); startedRef.current = true; setPrompted(false); }
    addRipple();
  }, [playing]);

  return (
    <div style={{ position:"fixed", bottom:26, insetInlineEnd:26, zIndex:200,
                  display:"flex", flexDirection:"column", alignItems:"flex-end", gap:8 }}>
      {/* <AnimatePresence>
        {prompted && (
          <motion.div initial={{ opacity:0, x:20 }} animate={{ opacity:1, x:0 }} exit={{ opacity:0, x:20 }}
            style={{ background:C.navyPanel, borderRadius:8, padding:"8px 14px",
                     boxShadow:C.shadowGold, border:`1px solid ${C.goldLine}`,
                     fontSize:".78rem", color:C.cream, fontFamily:"Cairo,sans-serif", whiteSpace:"nowrap" }}>
          </motion.div>
        )}
      </AnimatePresence> */}
      <div style={{ position:"relative" }}>
        {ripples.map(id => (
          <div key={id} style={{ position:"absolute", inset:0, borderRadius:"50%",
                                  background:C.gold, animation:"rippleGold .9s ease-out forwards" }} />
        ))}
        <button onClick={toggle}
          style={{ position:"relative", width:56, height:56, borderRadius:"50%",
                   background:C.navyDeep, border:`2px solid ${C.goldBright}`, cursor:"pointer",
                   display:"flex", alignItems:"center", justifyContent:"center", boxShadow:C.shadowGold }}>
          <Siren className={playing ? "beacon-spin" : ""} style={{ width:23, height:23, color:C.goldBright }} />
        </button>
      </div>
      {/* <AnimatePresence>
        {playing && (
          <motion.div initial={{ opacity:0, y:4 }} animate={{ opacity:1, y:0 }} exit={{ opacity:0, y:4 }}
            style={{ background:C.navyPanel, borderRadius:18, padding:"5px 13px",
                     border:`1px solid ${C.goldLine}`, fontSize:".7rem", color:C.creamMuted, fontFamily:"Cairo,sans-serif" }}>
            نشيد التخرج
          </motion.div>
        )}
      </AnimatePresence> */}
    </div>
  );
});

/* ════════════════════════════════════════════
   INTRO
════════════════════════════════════════════ */
const IntroAnimation = memo(({ onComplete }) => {
  const [showText, setShowText] = useState(false);
  useEffect(() => {
    const t1 = setTimeout(() => setShowText(true), 1500);
    const t2 = setTimeout(onComplete, 4000);
    return () => { clearTimeout(t1); clearTimeout(t2); };
  }, [onComplete]);
  return (
    <motion.div exit={{ opacity:0 }} transition={{ duration:.7 }}
      style={{ position:"fixed", inset:0, zIndex:300, background:C.navyDeep,
               display:"flex", alignItems:"center", justifyContent:"center", overflow:"hidden" }}>
      <div style={{ position:"absolute", inset:0, opacity:.14,
        backgroundImage:`radial-gradient(${C.goldBright} 1px, transparent 1px)`, backgroundSize:"30px 30px" }} />
      <div style={{ display:"flex", flexDirection:"column", alignItems:"center", position:"relative", zIndex:10 }}>
        <Medallion size={190} animate />
        <motion.div initial={{ opacity:0, y:18 }} animate={showText ? { opacity:1, y:0 } : {}}
          transition={{ duration:.7 }} style={{ marginTop:28, textAlign:"center" }}>
          <p style={{ fontFamily:"Cairo,sans-serif", color:C.creamMuted, letterSpacing:".08em", fontSize:".8rem", marginBottom:10 }}>
            أكاديمية الشرطة
          </p>
          <h1 className="shimmer-text" style={{ fontFamily:"Amiri,serif", fontWeight:700, fontSize:"clamp(1.9rem,5.5vw,2.9rem)" }}>
            الملازم محمد رفاعي لبنة
          </h1>
          <p style={{ fontFamily:"Cairo,sans-serif", color:C.creamMuted, marginTop:10, fontSize:".95rem" }}>
            بمناسبة التخرج واستلام رتبة الملازم
          </p>
        </motion.div>
      </div>
    </motion.div>
  );
});

