/* ════════════════════════════════════════════
   STAMP SEAL — ceremonial closing mark
════════════════════════════════════════════ */
const StampSeal = memo(({ size = 108 }) => {
  const c = size / 2;
  const rOuter = c - 4;
  const rInner = c - 16;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ transform:"rotate(-6deg)" }}>
      <circle cx={c} cy={c} r={rOuter} fill="none" stroke={C.goldBright} strokeWidth={1.5} opacity={.85} />
      <circle cx={c} cy={c} r={rInner} fill="none" stroke={C.goldBright} strokeWidth={1} strokeDasharray="1.5 4" opacity={.7} />
      <g transform={`translate(${c},${c})`}>
        <Star x={-15} y={-15} width={30} height={30} color={C.goldBright} fill={C.goldBright} strokeWidth={0.5} opacity={.9} />
      </g>
    </svg>
  );
});

